import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>工具不用猜，是怎么命中80KB这样的精确文件大小的？答案是一种简单又优雅的算法，叫二分搜索。</p>\n<p>二分搜索只要几次测试，就能为你的图片找到最佳画质设置。它从不猜测，从不满足于整数，也从不浪费画质。</p>\n<p>这篇文章会讲清楚搜索是怎么工作的、为什么它胜过手动的画质滑块，以及它的局限在哪里。</p>\n<h2 id=\"the-problem\">问题：画质是没法预测的</h2>\n<p>每张图片压缩起来的表现都不一样。同样70%的画质，一张人像可能重90KB，一张风景照可能重150KB。</p>\n<p>这种不可预测，让手动的画质滑块对精确目标毫无用处。设成70%再碰运气，根本不是办法。</p>\n<p>你也可以手动一个一个试画质，但每次测试都要时间。手动找到最佳设置，可能要试二十次。</p>\n<p>工具用搜索解决了这个问题。它会系统地测试不同的画质档位，直到找到能塞进目标的最高画质。</p>\n<p>理解了搜索，你就能信任结果。这不是魔法，这是方法。</p>\n<h2 id=\"binary-search-basics\">二分搜索，用大白话讲</h2>\n<p>二分搜索作用在一个排好序的区间上。画质从低到高，文件大小随着画质上升而上升，所以这个区间是完美有序的。</p>\n<p>搜索从中间开始。它测试画质50，检查结果能不能塞进目标。</p>\n<p>结果能塞进去，最佳画质一定高于50。搜索移到上半区，测试75。</p>\n<p>结果塞不进去，最佳画质一定低于50。搜索移到下半区，测试25。</p>\n<p>每次测试都会把剩下的范围砍掉一半。大约七次测试之后，搜索就能把最佳画质缩小到一个点。</p>\n<h2 id=\"worked-example\">实例演示：命中100KB</h2>\n<p>想象一张照片，目标是100KB。搜索先测试画质50。</p>\n<p>画质50时，文件重70KB。能塞进去，所以最佳画质在50以上。搜索测试75。</p>\n<p>画质75时，文件重120KB。太大了，所以最佳画质在50到75之间。搜索测试62。</p>\n<p>画质62时，文件重95KB。能塞进去，所以范围缩小到62到75之间。搜索测试68。</p>\n<p>画质68时，文件重104KB。又太大了，所以范围变成62到68。再测试几次，就定在65，落在99KB。</p>\n<p>整个过程只要几秒钟。同样的工作让人手动来做，要花很多分钟，还要有大得多的耐心。</p>\n<h2 id=\"why-not-linear\">为什么二分搜索胜过线性搜索？</h2>\n<p>线性搜索会按顺序测试每个画质档位：100、99、98，这样一路下来。它能用，但很慢。</p>\n<p>从100往下数到65，要测试35次。二分搜索大约七次就能找到。</p>\n<p>每次测试都要重新编码图片，这需要实实在在的时间。三十五次编码感觉很迟钝，七次感觉是瞬间完成。</p>\n<p>二分搜索的扩展性也很好。区间是100还是1000，测试次数增长得很慢。</p>\n<p>这种效率就是工具即使处理大图片也感觉很快的原因。搜索只做找到最佳答案所需的最少工作。</p>\n<h2 id=\"quality-first\">为什么画质优先于尺寸？</h2>\n<p>搜索先在完整分辨率下运行。这是有意的设计，因为对大多数人来说，尺寸比画质上的一点点差别更重要。</p>\n<p>完整尺寸、画质稍微低一点的照片，通常比尺寸小、画质高的照片看起来更好。眼睛先注意到大小，再注意到压缩。</p>\n<p>只有完整尺寸下搜索失败时，缩放才开始。工具会测试更小的尺寸，在每一步上重新运行画质搜索。</p>\n<p>这个顺序保护了你的图片。它保留了你已有的像素，只牺牲你看不见的那部分画质。</p>\n<p>网站要求精确尺寸时，这个顺序依然成立。工具会更努力地只调画质，目标达不到时也会提醒你。</p>\n<h2 id=\"scaling-steps\">尺寸缩放的步骤是怎么工作的？</h2>\n<p>只调画质达不到目标时，工具会逐步缩小尺寸。它会测试90%、80%等缩放比例。</p>\n<p>在每个尺寸下，它都会重新运行二分搜索，找最佳画质。也就是说，每个尺寸都有自己的最佳画质设置。</p>\n<p>工具在第一个能塞进目标的尺寸停下来。90%的图片能命中目标，就保留它，而不是没必要地降到80%。</p>\n<p>步骤小是有意的。逐步缩小能在达到目标的同时，尽量保留最多的尺寸。</p>\n<p>对大多数图片来说，缩放很少需要。它主要出现在目标特别紧，或者原图特别大的时候。</p>\n<h2 id=\"accuracy-limits\">精确度及其局限</h2>\n<p>搜索落在目标附近非常近的位置，通常在几KB以内。它会故意瞄准上限以下一点点，留出安全余量。</p>\n<p>这个余量能应对四舍五入。设备上显示100KB的文件，精确字节数可能是100.4KB，余量能盖住这个差距。</p>\n<p>有些图片会难倒搜索。细节极其丰富的照片配上极小的目标，可能需要把尺寸缩到结果没法用的程度。</p>\n<p>遇到这种情况，工具会诚实地报告没达成。它宁愿告诉你目标做不到，也不愿递给你一张毁掉的图片。</p>\n<p>精确度也取决于格式。JPG和WebP给搜索提供了精细的控制，PNG几乎没有控制，所以PNG的目标常常没达成。</p>\n<h2 id=\"vs-manual\">二分搜索与手动的画质滑块对比</h2>\n<p>手动滑块让你选一个画质数值再碰运气。大多数人会选70或80这样的整数，而这很少是最合适的选择。</p>\n<p>你的图片最佳画质可能是63或71。人永远猜不到这个数字，但搜索几秒钟就能找到。</p>\n<p>手动滑块还浪费时间。每次测试都要改滑块、等一会儿、检查大小，反复进行，直到运气好。</p>\n<p>搜索完全去掉了猜测。你说出目标，工具找到能塞进去的最佳画质。</p>\n<p>这就是目标压缩工具真正的优势。它把反复试错的杂活，变成一次有信心的点击。</p>\n<h2 id=\"batch-search\">批量模式里的搜索</h2>\n<p>批量模式下，搜索会为每张图片单独运行。每张文件都有自己的最佳画质设置，尽管它们共享同一个目标。</p>\n<p>一张简单的证件照可能定在画质82，一张细节丰富的风景照可能定在61。两者用各自最好的设置命中了同一个目标。</p>\n<p>汇总会逐个文件记录。它会显示哪些文件达成了目标、哪些没达成，你可以逐个修复没达成的。</p>\n<p>批量搜索比单张搜索花的时间更长，但比一张一张手动压缩快得多。重复的工作由工具替你做了。</p>\n<p>先预览批量里最难的那些文件。它们最可能没达成目标，或者损失了可见的画质。</p>\n<h2 id=\"when-search-fails\">搜索帮不上忙的时候</h2>\n<p>搜索创造不出不存在的数据。一张又小又模糊的原图，在任何目标下都变不成一张锐利的图片。</p>\n<p>它也打败不了物理规律。细节丰富的照片压到2KB是不可能的，任何搜索算法都改变不了这一点。</p>\n<p>它修不好错误的格式。目标很紧的PNG照片，不管搜索多聪明都会没达成，因为PNG减不掉足够的体积。</p>\n<p>遇到这些情况，就改输入条件。用更好的原图、换成JPG，或者把目标提高到能做到的大小。</p>\n<p>搜索是个强大的工具，但它在你的图片本身的限制内工作。好的输入进来，好的结果出去。</p>\n<h2 id=\"search-history\">二分搜索从哪里来？</h2>\n<p>二分搜索是计算机领域最古老的算法之一。它出现在电话簿、词典和猜数字游戏里，任何需要搜索排好序的列表的地方都有它。</p>\n<p>想法很简单：检查中间，扔掉一半，再重复。这和在词典中间翻开找一个词的逻辑是一样的。</p>\n<p>程序员用它来搜索任何大小的排序数据。一百万条数据的列表只要二十次测试，这就是它无处不在的原因。</p>\n<p>在图片压缩里，排好序的列表就是画质区间。文件大小随画质上升而上升，所以区间是有序的，二分搜索完美适用。</p>\n<p>了解这段历史能帮你信任这个方法。它不是什么新花招，而是一个经过验证的想法用在了新问题上。</p>\n<h2 id=\"search-vs-ai\">搜索与猜测：为什么方法胜过直觉？</h2>\n<p>人的直觉不擅长选画质数字。我们偏爱70或80这样的整数，而它们很少是某张图片的最佳选择。</p>\n<p>直觉还会停得太早。一个人找到一个能塞进去的画质，通常就停下了，哪怕稍微高一点的画质也能塞进去。</p>\n<p>搜索没有这些偏见。它会系统地测试，只有把范围缩小到唯一最佳值时才停下来。</p>\n<p>这种有条理的方法就是全部优势。工具并不比你懂得更多，它只是比你检查得更仔细。</p>\n<p>相信方法，而不是相信直觉。它找到的数字每次都比你猜的数字更好。</p>\n<h2 id=\"quality-steps\">画质步进有多精细？</h2>\n<p>画质通常从1到100来测量，一共有一百种可能的设置。搜索大约测试其中七种，就能找到最佳的。</p>\n<p>七次测试就够了，因为每次测试都会把范围砍掉一半。七次对半砍下来，100的范围已经缩小到不到1。</p>\n<p>更精细的步进只会增加测试次数，看不见好处。画质65和66之间的差别，眼睛根本看不出来。</p>\n<p>搜索在进一步测试没法改善结果时就停下来。这个停止点是算法内置的，不是人工选的。</p>\n<p>效率在这里很重要。测试越少，结果越快，结果越快，工具就越让人喜欢用。</p>\n<h2 id=\"edge-cases-search\">边缘情况：区间没有排好序时怎么办？</h2>\n<p>二分搜索需要一个排好序的区间：画质越高，文件必须越大。这几乎总是成立的，但不完全总是。</p>\n<p>画质上微小的变化，偶尔会因为编码器四舍五入的方式，让高一点的画质反而做出稍微小一点的文件。</p>\n<p>这些波动很小，搜索容忍得了。它瞄准的是目标以下一点点，所以小波动没法把结果推过上限。</p>\n<p>换格式会完全打破顺序。画质90的PNG可能比画质50的JPG还大，这就是搜索按格式单独运行的原因。</p>\n<p>工具会悄悄处理这些边缘情况。你看到的是干净的结果，算法在幕后处理了那些混乱。</p>\n<h2 id=\"search-and-scaling\">搜索与缩放如何配合工作？</h2>\n<p>画质搜索和尺寸缩放是两个循环，一个套着另一个。外层循环尝试尺寸，内层循环在每个尺寸下搜索画质。</p>\n<p>工具从完整尺寸开始，搜索画质。没有画质能塞进去时，它把尺寸缩小一步，再搜索一次。</p>\n<p>这种嵌套很高效。它避免了测试尺寸和画质的每一种组合，那样要花长得多的时间。</p>\n<p>结果就是，在你的目标下，尺寸最大、画质最好的图片。在搜索空间内，没有其他组合能胜过它。</p>\n<p>理解了这种嵌套，就能理解工具的行为。一张文件缩小了尺寸，是因为完整尺寸下没有画质能塞进去。</p>\n<h2 id=\"future-search\">目标搜索的未来会怎样？</h2>\n<p>搜索还可以变得更聪明。未来的版本可能在测试之前，就根据图片内容预测最佳画质。</p>\n<p>内容感知的搜索会从离答案更近的地方开始，需要的测试更少。人像和风景会从不同的画质猜测开始。</p>\n<p>目前，普通的二分搜索已经够快了。七次测试只要几秒钟，结果已经是能塞进去的最佳画质。</p>\n<p>原则不会变。说出目标，系统地搜索，交付能塞进去的最锐利的文件。</p>\n<p>正是这个原则，让目标压缩工具感觉毫不费力。复杂性住在算法里，用户只看到干净的结果。</p>\n<p>想看自定义目标的完整指南，可以读<a href=\"/zh/blog/mu-biao-wen-jian-da-xiao-ya-suo-qi-wan-zheng-zhi-nan/\">目标文件大小压缩工具：完整指南</a>。想看动手操作的步骤，可以看<a href=\"/zh/blog/ru-he-ba-tu-pian-ya-suo-dao-jing-que-kb-da-xiao/\">如何把图片压缩到精确的KB大小</a>。想亲自试一试，打开<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>，输入任意大小就行。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"什么是二分画质搜索？","answer":"它是一种找到能塞进文件大小目标的最高画质设置的方法。工具测试一个画质档位，检查结果大小，再把剩下的范围砍掉一半、重新测试。大约七次测试之后，就能把最佳画质缩小到一个具体的数字。"},{"question":"为什么搜索从画质50开始？","answer":"从区间中间开始，正是二分搜索快的原因。每次测试都能排除一半的可能性，所以几步就能收敛。从顶部往下数，要花多得多的测试次数。"},{"question":"搜索能找到63这样的画质，而不是60或70这样的整数吗？","answer":"可以，而且这正是它主要的优势。你的图片最佳画质很少是整数。搜索会测试精确的数值，定在最合适的设置上，比如63或71，这是人永远猜不到的。"},{"question":"搜索对每张图片的工作方式都一样吗？","answer":"方法一样，结果因图片而异。同样目标下，一张简单的证件照可能定在画质82，一张细节丰富的风景照可能定在61。每张图片都有自己的搜索和自己的最佳设置。"},{"question":"为什么工具有时缩小尺寸，而不是只降低画质？","answer":"完整尺寸下即使最低可用画质也达不到目标时，尺寸是唯一剩下的杠杆。工具会逐步缩小像素尺寸，在每一步上重新运行画质搜索，在第一个能塞进目标的尺寸停下来。"},{"question":"其他CompressMyPic工具也用二分搜索吗？","answer":"是的。50KB、100KB、200KB和500KB的固定尺寸压缩工具都用同样的二分画质搜索，只是各自的目标是预设好的。目标压缩工具只是让你输入任意数字，而不是用固定的那一个。"}];
